47],[41.124015,0.798286],[41.124038,0.798327],[41.124066,0.798372],[41.124089,0.798415],[41.124112,0.798459],[41.124143,0.7985],[41.124159,0.798552],[41.12417,0.798602],[41.124181,0.79865],[41.124213,0.798682],[41.124233,0.798711],[41.124251,0.798747],[41.124274,0.79879],[41.124291,0.79884],[41.124313,0.79889],[41.124339,0.798933],[41.124363,0.798977],[41.124383,0.79902],[41.1244,0.799064],[41.124412,0.799096],[41.124454,0.799135],[41.124494,0.799155],[41.124531,0.79917],[41.124566,0.799177],[41.124597,0.799181],[41.124618,0.799226],[41.124628,0.799272],[41.124645,0.799313],[41.124662,0.799361],[41.124676,0.799414],[41.124685,0.799463],[41.124698,0.799512],[41.124701,0.799565],[41.124716,0.799611],[41.124743,0.79965],[41.12477,0.799692],[41.124799,0.799734],[41.12485,0.799768],[41.124871,0.799806],[41.124898,0.799849],[41.12491,0.799896],[41.124915,0.799942],[41.124921,0.799988],[41.124949,0.799962],[41.12495,0.799901],[41.12494,0.799841],[41.124941,0.799786],[41.124955,0.799738],[41.124965,0.799687],[41.12499,0.799652],[41.125025,0.799671],[41.125049,0.799711],[41.125068,0.799755],[41.125086,0.799805],[41.125108,0.799853],[41.125133,0.799901],[41.125153,0.799945],[41.125186,0.799989],[41.125211,0.800035],[41.125236,0.800084],[41.125253,0.800131],[41.125269,0.800179],[41.125286,0.800221],[41.125304,0.800258],[41.125339,0.800261],[41.125369,0.800241],[41.125403,0.800235],[41.125445,0.800213],[41.125491,0.800219],[41.125531,0.800231],[41.125583,0.800252],[41.125639,0.800241],[41.125695,0.800221],[41.12574,0.800202],[41.125783,0.800203],[41.125827,0.800217],[41.125862,0.800221],[41.125898,0.800234],[41.125927,0.800229],[41.125959,0.800206],[41.125993,0.800213],[41.125997,0.800217]]'::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_km double precision;
  v_gap double precision;
  v_center double precision;
  v_closure double precision;
  v_invalid integer;
begin
  select h.id,h.latitude,h.longitude,h.distance_km,t.status
    into v_route from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
  where h.id='osm-relation-10582713'
    and h.source='openstreetmap'
    and h.name='Marçà-Capçanes-Marcà. Dos mon en un de sol'
    and h.official_url='https://www.turismepriorat.org/ca/dos-mons-en-un-de-sol'
    and exists(select 1 from public.hiking_route_regions m
      where m.route_id=h.id and m.published);
  if not found then raise exception 'Priorat route identity or region changed'; end if;
  if v_route.status='ready' then return; end if;
  with p as (
    select ordinality n,(point->>0)::float8 lat,(point->>1)::float8 lon
    from jsonb_array_elements(v_coords) with ordinality as x(point,ordinality)
  ), s as (
    select *,lag(lat) over(order by n) pl,lag(lon) over(order by n) po from p
  ), d as (
    select case when pl is null then 0 else
      6371*2*asin(sqrt(least(1,power(sin(radians(lat-pl)/2),2)
        +cos(radians(pl))*cos(radians(lat))
        *power(sin(radians(lon-po)/2),2)))) end step_km,
      6371*2*asin(sqrt(least(1,power(sin(radians(lat-v_route.latitude)/2),2)
        +cos(radians(v_route.latitude))*cos(radians(lat))
        *power(sin(radians(lon-v_route.longitude)/2),2)))) center_km,
      (lat between 40 and 43 and lon between -1 and 3) valid from s
  ) select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_km,v_gap,v_center,v_invalid from d;
  select 6371*2*asin(sqrt(least(1,
    power(sin(radians(((v_coords->0->>0)::float8-
      (v_coords->(v_count-1)->>0)::float8)/2)),2)
    +cos(radians((v_coords->0->>0)::float8))
      *cos(radians((v_coords->(v_count-1)->>0)::float8))
      *power(sin(radians(((v_coords->0->>1)::float8-
        (v_coords->(v_count-1)->>1)::float8)/2)),2))))
    into v_closure;
  if v_count<>1237 or v_invalid>0 or v_route.distance_km is distinct from 11.000::numeric
    or abs(v_km/v_route.distance_km-1)>0.08
    or v_gap>0.10 or v_center>0.60 or v_closure>0.25
  then raise exception
    'Priorat GPX failed: points %, km %, gap %, center %, closure %, invalid %',
    v_count,v_km,v_gap,v_center,v_closure,v_invalid;
  end if;
  select jsonb_agg(jsonb_build_object('lat',(point->>0)::float8,
    'lon',(point->>1)::float8) order by ordinality) into v_points
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality);
  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values ('osm-relation-10582713','ready',jsonb_build_array(v_points),
    now(),true,'Turisme Priorat',
    'https://www.turismepriorat.org/sites/default/files/route/attachment/mara-capanes-mara0_0.gpx',
    true)
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,checked_at=excluded.checked_at,
    continuity_checked=true,geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;
  update public.hiking_routes set trace_available=true,published=true
    where id='osm-relation-10582713';
end
